                    { 948, "مبروك عطية", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من نعم الله على عباده أنه شرع لهم ما يصلحهم وحرم عليهم ما يفسدهم؛ فجعل رضاه حيث\nمنفعتهم، وجعل سخطه حيث مضرتهم؛ ومن هنا لا يخفى على عاقل لِمَ حرم الله الغرور\nوجعله من الحوائل دون دخول الجنة -كما أخبر بذلك المعصوم صلى الله عليه وسلم- وما كان لامرئ أن يدخل\nالغرور قلبه إذ الملك كله لله والعباد مستخلفون في الأرض يعمرونها لا ليتفاخروا ولا ليتكبروا\nوإنما لتعلو كلمة الله -تعالى- التي تقضي بالحق لكل العباد. في هذا الكتاب إطلالة على الذنب\nالأول )الغرور( الذي من أجله تكبر إبليس عَلى السجود لآدم فاستحق لعنة الله -عز وجل-\nعبرة لمن أراد السلامة من هذه الآفة الكبرى، فيعرض الكتاب في فصوله الثلاثة: مفهوم\nالغرور وماهيته التي يخلط كثير من الناس بينها وبين الثقة بالنفس والإخبار بالواقع. ثم يطوف في نماذج من الرسل الكرام الذين لم يقعوا في هذه الآفة مع أنهم لهم كل كمال بشري. ثم يسرد الكتاب عواقب الغرور ومآله ليتبين الخيط الأبيض من\nالخيط الأسود، ويظهر الصبح لذي عينين.\nالمؤلف : مبروك عطية\nسنة النشر : 2018", "/images/products/9789777951517.webp", "9789777951517", "الغرور وفتنة الانسان", null, 185m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 949, "جبران خليل جبران", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يحتوي كتاب \"البدائع والطرائف\" على أغلب الأصناف الأدبية: مقالات وخواطر وقصائد شعرية ومسرحيات.\n يواجه فيه تناقضات المجتمع الشرقي وآفاته، يضع حدًّا لتلك النرجسية غير المبررة، كما\n يذكرنا بأعلامنا الفكرية من خلال مجموعة مقالات لهم، مطع إياها ببورتريهات لهم\n بريشته. هذا الكتاب بالإجمال هو آية أدبية، ومتعة فكرية، ونظرات فلسفية، ورياضات روحية.\n\n المؤلف : جبران خليل جبران\n سنة النشر : 2018", "/images/products/9789777951531.webp", "9789777951531", "البدائع والطرائف", null, 155m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 950, "طارق امام", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ذات يوم كانت هناك مدينة قرر أهلها أن تصير بينا، لأنهم أرادوا أن يصبحوا إخوة رغم خصام الدم.. فحطموا حوائط بيوتهم وصنعوا أربعة حوائط هائلة لتصير المدينة كلها، بينها، بينهم. صاروا جميعًا أسرة واحدة، أو هكذا اعتقدوا، لكنهم كانوا مع كل صباح يفقدون واحدا منهم يغادر جثمانه البيت تاركا مكانه بقعة من الدماء. لم يُعرف أبدًا أي من سكان البيت الكبير كان القاتل، حتى تبقى اثنان، رجل وامرأة. لم يكن أحدهما بحاجة ليفكر أنه سيكون ضحية الآخر، لأن كليهما كان يعرف، أنه هو القاتل. يمكن قراءة مدينة الحوائط اللانهائية كقصص، وبنفس القوة تطرحعالما متصلا يجعلها قابلة للقراءة كرواية. إنها مجموعة قصصية استثنائية، تذكرنا بألف ليلة وليلة، فهي تضم عالماً تخيليا كاملا في عصر ومكان هما كل زمان ومكان. قد تبدو مدينة الحوائط مكانا غرائبيا، ولكن عند إزالة غطاء الاعتياد ستجد أنها تشبه كثيرا المدن التي نعيش فيها ! \nطارق إمام روائي وناقد مصري من مواليد 1977. أصدر تسعة كتب بين روايات ومجموعات قصصية، من أبرزها: \" هدوء القتلة\"، \"الحياة الثانية لقسطنطين كفافيس\"، \"ضريح أبي\"، بعده النقاد أحد أبرز المجددين في السرد المصري الحديث، فضلاً عن كونه أكثر كتاب جيله حصولاً على الجوائز ، منها جائزة ساويرس مرتين، جائزة وزارة الثقافة المصرية مرتين، جائزة الدولة التشجيعية جائزة سعاد الصباح، وجائزة متحف الكلمة العالمية.                                                                 \nالمؤلف : طارق امام\n  سنة النشر :- 2018", "/images/products/9789777951579.webp", "9789777951579", "مدينة الحوائط اللانهائية", null, 250m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 951, "أحمد الشهاوى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لا أراني ” ، كتابُ أسرارٍ فيه ما فيه من العشقِ والتصوفِ الذي يُضاف إلى مُنجز أحمد الشهاوي من أدب العشق . أنت في هذا الكتاب أمام حُبٍّ مقدَّس ، وحكمة تقودُك إلى قلبك ؛ كيْ ترى من تحبُّ بعينيْ رُوحك التي تبحثُ عن نورها التائه ، وخلاصها النهائي\nالمؤلف : احمد الشهاوى\nسنة النشر : 2018", "/images/products/9789777951524.webp", "9789777951524", "لا ارانى", null, 185m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 952, "أحمد المسلمانى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"إنَّ نسبة نابليون إلى فرنسا كنسبة محمد علي إلى مصر، هذا من مواليد جزيرة لم تكن فرنسية، وذاك من مواليد مدينة لم تكن مصرية، وكلا الرجلين قاد وطنه الجديد إلى المجد...\nإن أدولف هتلر مواطن نمساوي ولم يتحدث أحد عن نمساوية هتلر الذي لم يكن مواطنًا ألمانيًّا حتى عام 2391م...\nإنَّ القيصرة «كاترين الكبرى» قيصرة روسيا كانت ألمانيّة.. كما أنَّ العائلة المالكة السويدية من أصول فرنسية.. ومع هذا فإن أحدًا لا يقول عن الملك كارل جوستاف وهو يمنح جوائز نوبل.. إنه ملك فرنسي!\".\n*\nتمثِّل أطروحة \"الهندسة السياسة\" جديدًا في الفكر السياسي العربي.. وقد نجح الكاتب عبْر أسلوب شيق ومعلومات غزيرة.. وكذلك عبْر تحليلات هادئة ورصينة.. في أن يجعل من التاريخ والسياسة.. مجالاً ممتعًا للتفكير والتأمل ومنصّةً قويةً في صناعة الأمل.\nإن كتاب \"الهندسة السياسية\".. ليس كتابًا في الهندسة الفكرية أو السياسة العملية وحدهما، ولكنه كتاب في المنطق والتاريخ والجغرافيا.. وكذلك الدين والثقافة.. والقوة الصلبة والقوة الناعمة. إنّه من ذلك النمط الموسوعي من الكتابة التي يندُر توافرها في المكتبة العربية.\n \nأحمد المسلماني .. كاتب وإعلامي مصري ـ تخرج في قسم العلوم السياسية  بكلية  الاقتصاد والعلوم السياسية ـ جامعة القاهرة. صدر له العديد من الكتب والمقالات الصحفية.. وقد عمل مستشارًا للدكتور أحمد زويل،  ثم مستشارًا لرئيس الجمهورية .\nالمؤلف : احمد المسلمانى\nسنة النشر : 2018", "/images/products/9789777950091.webp", "9789777950091", "الهندسة السياسية", null, 225m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 953, "ابراهيم عبد المجيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لاتزال الإسكندرية منبع الفنانين، وستستمر\nرغم أي تدهور فيها. ولم أكن أعرف وأنا صغير\nأجري وراء الأفلام والسينمات السر وراء دور\nالسينما الكثيرة في الإسكندرية، وأنها أصل\nهذا الفن الجميل الذي كان أحد أهم ملامحها\nالروحية .»\n«حكايات رائعة لا تُمَلّ يحكيها الكاتب الكبير\nإبراهيم عبد المجيد عن السينما منذ طفولته تعيد\nإلينا بشرا جميلا ومدنا اختفت وسينمات هُدِمَت\nوأفلاما لا تُنسى، وكيف تقدم فهمه للسينما مع\nالزمن، وأثّر ذلك على حياته الأدبية\nالمؤلف : ابراهيم عبد المجيد\nسنة النشر : 2018", "/images/products/9789772937424.webp", "9789772937424", "انا والسينما", null, 300m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 954, "نهلة كرم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«توقعت أن يمسك يدي ويقول لي ألا أخاف،\n لكنه بد من ذلك سألني، وهو ينظر في عيني:\n وهل تريدين الشعور بالأمان فع ؟ًال\n ارتبكت ونظرت ناحية النافذة وأجبته:\n بالطبع، ومن منا لا يريد الشعور بالأمان؟\n لم أجد إجابة منه نظرت له، كان ينظر لي\n بتشكك تام، هززت رأسي نفيًا: لا، لا أحب أن\n أشعر بالأمان.\n – لهذا نحن معًا .»\n ***\n الارتباط كلمة بسيطة تستدعي الفرحة\n للبعض، لكنها ليست سوى رعب حقيقي\n لآخرين، حاولت سارة كثيرًا أن تأخذ الكلمة\n ببساطة لكنها في كل مرة كانت تصل إلى النتيجة\n نفسها، فهل ستكون هذه المرة مختلفة في شيء؟\n المؤلف : نهلة كرم\n سنة النشر : 2018", "/images/products/9789777951432.webp", "9789777951432", "المقاعد الخلفية", null, 250m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 955, "دان براون", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مع بدء الأمسية، يستغرق لانغدون وبقية\n الضيوف البالغ عددهم بضع مئات في عرض\n رائع، سرعان ما يدرك لانغدون أنه سيكون\n أكثر إثارة للجدل مما تخيل بكثير. لكن الحدث\n المنظم بدقة بالغة يغرق فجأة في حالة من\n الفوضى، ويصبح اكتشاف كيرش الثمين على\n شفير الضياع إلى الأبد. في أعقاب ذلك، يواجه\n لانغدون تهديدات خطرة تجبره على الفرار من\n بيلباو. ومعه أميرا فيدال مديرة المتحف الأنيقة\n التي كانت تتعاون مع كيرش للتحضير لذلك\n الحدث الاستفزازي. معا، يفران إلى برشلونة في\n بحث عن كلمة سر مشفرة من شأنها أن تكشف\n سر كيرش.\n المؤلف : دان براون\n سنة النشر : 2018", "/images/products/9786140124257.webp", "9786140124257", "الاصل", null, 235m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 956, "مصطفى النشار", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لقد بذل الفلاسفة منذ فجر الحضارات الإنسانية وحتى اليوم جهودا جبارة بدت في تأملاتهم وتبلورت في كتاباتهم في سبيل إرساء مبادئ القانون العادل الذي يحافظ على ذلك التوازن المفقود بين الحقوق والواجبات، بين من يملكون القوة والسلطة وبين من لا يملكون حتى قوت يومهم! بين دعاة الحرب والاستيلاء والسيطرة والاغتصاب وبين دعاة السلام والتعاون والمساواة والمحبة بين الأفراد والشعوب والدول.\nإن حلما طوباويا يراود كل هؤلاء الفلاسفة حول أسس وجود المجتمعات العادلة التي يعيش في إطارها أفراد البشر متمتعين بحقوقهم العادلة في ظل عالم لا ظلم فيه ولا استبداد، عالم لا تُستخدم فيه القوة الغاشمة ضد أحد منهم تحت أي مسمى من المسميات!!\nلكن السؤال الملح هو: هل نجح الفلاسفة ذات يوم في الوصول إلى هذا الحلم الطوباوي الذي يمكن أن يقنع كل البشر لدرجة أن يعملوا على تنفيذه والعيش تحت ظله وفي إطاره القانوني العادل؟!\nالمؤلف : مصطفى النشار\nسنة النشر : 2018", "/images/products/9789777951357.webp", "9789777951357", "فلسفة القانون واشكالياتها", null, 300m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 957, "محمد برادة", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تصدر هذه القراءة لـ 46 رواية عربية، يمتد تاريخ صدورها من 1966 إلى 2017، عن تصوّر يعتبر الرواية شكلا فنيا يصوغ الحياة التي يعاصرها الروائي صوْغا مُغايرا لما تتبدّى عليه في تفاصيل المعيش والمحسوس.\nليس المقصود بـ«الذات» في هذا السياق، ذاتَ الفرد الضيقة، المنحصرة في هموم وتفاصيل العادات الشخصية، وإنما نعني بها الذات في مجموع مكوناتها للفرد، ماديا ونفسيا، والأسئلة التي تشغله في حياته وصراعاته مع مؤسسات المجتمع ومع كل ما يجثم على حريته ليعوق الذات عن تحقيق تطلعاتها.\nوعندما نتحدث عن تخييل المجتمع والتاريخ، نقصد ضمنيا أن هناك روايات تتقصّدُ استيحاء المجتمع والتاريخ لتكشف عناصر وملامح لامرئية عند الوهلة الأولى، وفي الآن نفسه تجترح سيرورة التحويل والتغيير، إذ تسلط الضوء على أسئلةٍ تفرزها الصراعاتُ المجتمعية أوْ يُبلورها جريانُ التاريخ على المدى القصير والبعيد.\nالمؤلف : محمد برادة\n سنة النشر : 2018", "/images/products/9789777951449.webp", "9789777951449", "تخييل الذات والتاريخ والمجتمع", null, 300m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 958, "رضا عكاشة", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يُعدّ التحقيق الاستقصائي أحد القوالب الصحفية المستحدثة في الصحافة المصرية والعربية، ويحتاج هذا الشكل من فنون التحرير إلى دقة متناهية وصبر شديد ووقت طويل في استجلاء الفكرة، والتقصي عن أدق التفاصيل، وجمع الوثائق والمستندات والتسجيلات الصوتية والمرئية للكشف عن جوانب القصور والفساد، وكل ما هو مسكوت عنه، تمهيدًا لتدارك العيوب وإصلاح المعوج. لقد أصبح التحقيق الاستقصائي أحد مجالات التميز والتفرد للوسائل الإعلامية المطبوعة والمسموعة والمرئية والإلكترونية.  يقع هذا الكتاب في أربعة فصول، تضمن الفصل الأول: بيئة الصحافة الاستقصائية. وتناول الفصل الثاني: فن التحقيق الاستقصائي. وجاء الفصل الثالث: الاستقصاء وفنون الأداء. وأخيرًا الفصل الرابع: الصحافة الاستقصائية.", "/images/products/9789777951296.webp", "9789777951296", "التحقيق الاستقصائى", null, 275m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 959, "ايمن منصور ندا", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يحتل مفهوم الرأي العام مكانة مهمَّة في الخطابين الرسمي والشعبي في عالمنا العربي بل وفي العالم أجمع، غير أن مفهوم الرأي العام لا يزال غامضًا ولا تزال استخداماته وتطبيقاته بعيدة عن جوهر استخداماته الأصلية. وعلى الرغم من احتلال مفهوم الرأي العام وقياساته تلك المكانة المهمة فإنه لا يزال يعاني من «أخطاء» نظرية مفاهيمية عديدة من ناحية، ومن «خطايا» عملية تطبيقية كثيرة من ناحية أخرى.  وهذا الكتاب هو محاولة تهدف إلى تجاوز الأزمة في استطلاعات وقياسات الرأي العام، يهدف المؤلف من خلاله إلى محاولة تقديم الرأي العام في الدراسات العربية ويخلصه من عديد من الشوائب التي لصقت به. فهو كتاب نظري تطبيقي يقدم لقارئه مجالًا واسعًا من المقاربات النظرية الذائعة من التجارب العملية المستمدة من عشرات الاستطلاعات التي أجريت وتم عرض نتائجها.                 اسم المؤلف :- ايمن منصور ندا                                 سنة النشر :- 2017", "/images/products/9789777951401.webp", "9789777951401", "الراى العام وقياساته رؤى نظرية وتطبيقات", null, 360m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 960, "شيماء سراج", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يتميز المحتوى العلمي للكتاب بالشمول والبساطة في الوقت ذاته ، من خلال عرض\nمراحل ومكونات عملية التقييم ، بدءًا من بحث فكرة المشروع ، ومرورًا بمراحل التقييم\nالمختلفة: التسويقية، والفنية، والمالية، والاقتصادية، والبيئية، والتنظيمية.\nويضاف إلى سمة الشمول أن إطار العرض المتكامل يتسق مع المنهج العلمي الذي تتبعه\nمنظمة الأمم المتحدة للتنمية الصناعية(يونيدو)، وهو مايتيح للمستفيدين من هذا المرجع\nالقيم إعداد تقارير متكاملة، تلقى قبولاً من مؤسسات التمويل والتقييم على المستويات\nالوطنية والإقليمية والدولية، واضعًا في الاعتبار عدم اقتصار منهج يونيدو على المشروعات\nالصناعية فحسب، بل امتداده كذك إلى مختلف قطاعات النشاط السلعي والخدمي.\nويستهدف الكتاب فئات عديدة، بدءًا من البمتدئين وغير المتخصصين في علم دراسات\nالجدوى من فئة الطلاب الجامعيين، ووصولًا إلى المتخصصين من منظمات الأعمال\nوالمنظمات الحكومية وغير الحكومية لإعطاء صورة مبسطة ومتكاملة عن المراحل المختلفة\nالمرتبطة بدراسات الجدوى، التي تتيح اختيار المشروع الاستثماري الأفضل من بين مشروعات\nالاستثمار المتنافسة.\nالمؤلف : شيماء سراج\nسنة النشر : 2018", "/images/products/9789772937400.webp", "9789772937400", "تقييم المشروعات الاستثمارية وخطوات دراسات الجدوى وفقا لمنهج منظمة الأمم", null, 240m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 961, "عمرو حسين", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هى رواية يلعب فيها الخيال و الواقع دورًا متبادلًا ، بحيث يلتبس على\nالقارىء بتداخل الصور وتبدل الأدوار،فحين ينظر القارىء وقائعها\nيكتشف أنها محض خيال، وعندما يسبح مع موجات أحداثها\nالمتدافعة يصطدم بصخور الواقع!\nهذه رواية مشوقة تدور حول سرقة لوحة شهيرة نادرة من متحف،\nجرت من حولها المؤامرات والحيل والألاعيب ... ترى ماذا\nحدث؟!.. وكيف مضت حواراتها وانتهت؟!\nالمؤلف : عمرو حسين\nسنة النشر : 2018", "/images/products/9789777951418.webp", "9789777951418", "تاهيتى", null, 115m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 962, "صلاح اسماعيل", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يعالج هذا الكتاب الموضوعات الأساسية في فلسفة اللغة وهي المعنى\nوالإشارة والصدق، بالإضافة إلى تعلم اللغة ومعرفتها. ويعرض بأسلوب\nرصين رشيق وعبارات واضحة الدلالة نظريات الفلاسفة المعاصرين في هذه\nالموضوعات بداية من فتجنشتين ، ومرورا بكواين وتشومسكي وجرايس،\nحتي جون سيرل في وقتنا الحالي.\nوستجد فيه إجابات عن أسئلة من قبيل: كيف نتعلم اللغة؟ وما المعنى؟\nوكيف تعني الكلمات ماتعنيه؟ وماشروط صدق الجملة؟ وكيف يكون\nالتواصل اللغوي ممكنًا؟ وما الاختلاف بين معنى الجملة والمعنى الذي\nيقصده المتكلم، أو قل ما الاختلاف بين علم الدلالة وعلم الاستعمال؟\nالمؤلف : صلاح اسماعيل\nسنة النشر : 2018", "/images/products/9789777951425.webp", "9789777951425", "فلسفة اللغة", null, 330m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 963, "يحيى يخلف", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "اليد الدافئة هى مخزون دفء إنساني، يد مانحة لحب ينقي الحياة من\nالشوائب، ويمثل في هذا الصقيع الدولي فسحة أمل من أجل عالم أكثر\nدفئا. تتحرك شخصيات الرواية في أمكنة وأزمنة متعددة، بين حاضر\nوماض ، بين أحلام وخيال وفنتازيا وسحر مخيلة. حكايات تتوالد،\nحكاية أحمد ونرمين اللذين يلتقيان على رصيف الوطن ويجمعهما واقع\nمن فضة وخيال من ذهب، وحكاية سمعان وصوفي اللذين يجمعهما\nنداء الغريب إلى الغريبة، في متاهات اللجوء. وحكايات أخرى\nلشخصيات تنبت مثل الزهور من بين الصخور، وتشرئب أعناقها نحو فضاءات الحرية متحدية الحصار والغربة الأسلاك الشائكة.\nأحداث هذه الرواية تتوالد من صراع البقاء، مكللة بذهب الحب وهو إحدى\nركائز الحياة الإنسانية، مانحة الحياة روحا تتجدد لتواجه مكر التاريخ.\nالمؤلف : يحى يخلف\nسنة النشر : 2018", "/images/products/9789777951388.webp", "9789777951388", "اليد الدافئة", null, 220m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 964, "أحمد مجدي همام", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "نحن أمام رواية تمتزج فيها عوالم البشر وغير\nالبشر، مكونة ذلك العالم السحري الرائع بكل\nآفاق الخيال الرحبة من بلاد لم يسمع بها أحد،\nوأسماء لم تألفها أذن من قبل، آخذة من الواقع\nكل قيمه النبيلة وأخلاقياته السامية؛ لتشكل في\nنهاية الأمر \"جزيرة كابوريا\" أو ما أطلق عليه\nالمؤلف \"بلاد كل الخلق\"..\nالمؤلف : احمد مجدى همام\nسنة النشر : 2018", "/images/products/9789777951371.webp", "9789777951371", "الوصفة رقم 7", null, 200m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 965, "أحمد سالم", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "انتقلنا إلى المرحلة الابتدائية، وكلنا أمل في غد\n أفضل، ولكن هيهات، فقد اصطدمنا بواقع\n أكثر سوءًا حيث الذهاب إلى المدرسة سيرًا على\n الأقدام في رحلة شاقة، محملين بشنطة بها حوالي\n 541 كتابًا وكراسة، أو باستخدام الترام أو\n أوتوبيس المدرسة المتهالك في رحلة، تشبه رحلة\n الحجاج إلى منى وعرفات حيث 120 طالبًا في\n أوتوبيس 60 مقعدًا بخلاف حجر المشرفة،\n التي كانت تحمل في ضلوعها قلب مرات أبو\n سندريللا، وقفا السائق الذي كان في الغالب\n يجلس خارج الأوتوبيس، معلقًا في الشباك،\n تاركًا ذراعه فقط بالداخل لزوم السواقة.\n هذه المذكرات تجعلك تضحك بكل جوارحك،\n وتتأمل بكل كيانك أيضًا.. فهذه هي الحياة!\nالمؤلف : احمد سالم\n سنة النشر : 2018", "/images/products/9789777951364.webp", "9789777951364", "مذكرات عفريت", null, 155m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 966, "عمار على حسن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"قبل أن يغمض عينيه كان قد قرر ألا يفعل ما يطلبونه منه، ولو سجنوه، فسيجعل من زنزانته خلوة، وسيستعيد، على مهل، كل ما قرأه من كتب وأشعار الشيخ الكبير، وقد يكتشف فيها وبها ما لم يرد إلى ذهنه من قبل، ويصرخ في فرح طفولي غامر: أخيرًا وجدت الكنز. كان كنزًا غير الذي كلفوه بالبحث عنه، وظنوه بعيدًا تحت الأرض، ويمكن أن يستدل عليه من أصوات عجلى تجري على ألسنة العجائز، أو إشارات يبديها السائرون في شوارع القرى المتربة، وساحات المدن المنهكة، أو كلمات غامضة في وثائق وأوراق كتب تآكلت حوافها\".\n*\nليست هذه رواية عن شخص فحسب، وإنما عن زمن جميل يجرفنا الحنين إليه. وقد أبدع كاتبها حيلة فنية ليسرد حكاية، يتعانق فيها التاريخ بالتصوف، ويمتزج الواقع بالخيال، ويتفاعل الحقيقي مع العجيب، بوسعها  أن تخطف القارئ فيغوص في السطور متقلبا بين المتعة والدهشة.\n \nعمار علي حسن، عضو اتحاد الكتاب ونادي القصة ونقابة الصحفيين في مصر، له عشر روايات، أهمها: \"شجرة العابد\" و\"سقوط الصمت\" و\"السلفي\" و\"جبل الطير\" و\"بيت السناري\"، وله سبع مجموعات قصصية، أهمها: \"أحلام منسية\" و\"حكايات الحب الأول\"، و\"عطر الليل\"، وثلاثة كتب في النقد هي \"النص والسلطة والمجتمع\" و\"بهجة الحكايا\"، و\"أقلام وتجارب\" إلى جانب كتب في الاجتماع السياسي والتصوف. وتعد حول أعماله الأدبية تسع رسائل جامعية داخل مصر وخارجها.وتجارب\" إلى جانب كتب في الاجتماع السياسي والتصوف. وتعد حول أعماله الأدبية تسع رسائل جامعية داخل مصر وخارجها.\nالمؤلف : عمار على حسن\nسنة النشر : 2018", "/images/products/9789777951395.webp", "9789777951395", "خبيئة العارف", null, 220m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 967, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "وعاد إلى بيته وفي صدره فرحة هادئة.. وألقى\n بنفسه فوق فراشه وهو لا يحس من الدنيا إلا\n بنبضات قلبه.. ونظر إلى الوسادة التي بجانبه..\n فرآها بعين خياله.. رأى عينيها الواسعتين..\n وشفتيها المكتنزتين.. ووجنتيها العاليتين..\n وشعرها الأسود.. كأستار الليل.. وأغمض\n عينيه، وأخذ الوسادة بين ذراعيه، ولصق بها\n شفتيه..\n وقبَّل الوسادة الخالية!!\nالمؤلف : احسان عبد القدوس\n سنة النشر : 2018", "/images/products/9789777951326.webp", "9789777951326", "الوسادة الخالية", null, 250m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 968, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لقد قضت ليلتها على أحد أرصفة نهر\n السين، وهام بها هواء الليل عشقًا، فانتزع\n روحها وصعد بها إلى السماء! وسار في أحياء\n الحي اللاتيني وبين أصابعه الحلية التي أهدتها\n له «القتيلة » وعليها صورة العذراء.. إنهم لا\n يزالون - في الحي اللاتيني - يغنون ويرقصون،\n ولا تزال الفتيات يمرحن ويصرخن صرخات\n الجسد الذي لا يهدأ..\n إن الحي اللاتيني لا يبكي الأموات ولكنه يغني\n لهم! .»\nالمؤلف : احسان عبد القدوس\n سنة النشر : 2018", "/images/products/9789777951319.webp", "9789777951319", "صانع الحب", null, 185m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 969, "أحمد سالم سالم", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بدأت مظاهر الحداثة والتغريب تشق طريقها\nإلى مدينة القاهرة منذ أن وطأ الفرنسيون أرضها\nمحتلين أواخر القرن الثامن عشر، وما برحت\nهذه المظاهر في التعاظم إبان القرن التاسع عشر،\nمكتسحة أمامها أصالة ضربت بجذورها في هذه\nالأرض، فطبعت بطابع حضارتها الإسلامية كل\nما يمت للإنسان بصلة، مشكلة حياته وعاداته،\nفنونه وعمائره. فسارعت أسراب الرحالة\nالمستشرقين متدافعة من ذلك الوقت وكأنها\nمُودّعة أو مُشيّعة لتنهل من معين هذه الأصالة\nقبل أن يواريها النسيان خلف سيل الموضة\nالأوروبية الآخذة في السيادة يومًا بعد يوم.\nفجاء المغامر شغوفًا والفنان مصورًا والشاعر\nمستله والرحالة والمؤرخ واصفًّا ومحل .ًال ومن\nبين هؤلاء برز الإنجليزي الشهير إدوارد وليم\nلين، الذي أفرد هذا الوصف الفريد للقاهرة، بعين خبيرة دأبت على التمييز والوصف والتحليل،\nفنقل لنا من خلال فوتوغرافيا الكلمات ملامح قاهرة منتصف القرن التاسع عشر، حيث مفترق\nالطرق بين الأصالة والحداثة.\nالمؤلف : ادوارد لين بول\nسنة النشر : 2018", "/images/products/9789777951333.webp", "9789777951333", "القاهرة منتصف القرن التاسع عشر", null, 295m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 970, "ايمن فؤاد سيد", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتناول هذه الدراسة مفهوم التاريخ وتطور الفكرة التاريخية عند\n المؤلفين المسلمين وتطور معالجتهم لها مع اختلاف المدارس\n التاريخية أولا فى المدينة والبصرة والكوفة قم فى العراق فى\n القرنين الرابع والخامس للهجرة / العاشر والحادى عشر للميلاد ثم\n فى مصر وفى اقليم الشام والجزيرة (الذى غلب عليه فى الفنرة\n الممتدة بين القرنين السادس والثامن للهجرة/ الثانى عشر والرابع\n عشر للميلاد علماء الحديث والفقهاء وكتب الرجال) وفى اليمن\n حتى نهاية القرن التاسع الهجرى/الخامس عشر الميلادى اضافة الى\n المصادر التاريخية التى كتبها النصارى واليهود الذين عاشوا فى المجتمع\n الاسلامى وتناولت بعد ذلك دراسة الاشكال المستخدمة فى عرض\n المادة التاريخية وكذلك مناهج ونظريات النقد التاريخى عند المؤرخين\n المسلمين فى اطار نشأة وتطور الثقافة الاسلامية فى العموم فى الشرق\n مهد الاسلام ومركز ثقه الدائم وكذلك التفسير التاريخى ونظريات\n النقد التاريخى عند الغربيين وكتابة العرب المحدثين للتاريخ الاسلامى.\nالمؤلف : ايمن فؤاد سيد\n سنة النشر : 2018", "/images/products/9789777951340.webp", "9789777951340", "الكتابة التاريخية ومناهج النقد التاريخى عند المؤرخين المسلمين", null, 440m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 971, "نور عبد المجيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أؤمن أن المرأة تتحول في مرحلة ما لتصبح\nجنسًا ثالثًا لا هو رجل ولا هو امرأة.. جنس\nأكثر رحمةً وصفحًا وعطاءً... يزهد الكثير مما\nيلهث وراءه الجنس الأول و الثاني من البشر...\nرائع حقًّا أن تصبح من الجنس الثالث لكنه\nصعب... صعب جدًّا !!\n***\nيجب أن ننسى.. هناك خناجر يجب أن تبقى\nمغمدة في جراحها لأننا إن حاولنا تحريكها\nنموت... الألم ليس وحده طريق الحكمة...\nالحب الصادق طريق آخر لها!! وكلاهما خنجر\nفي الضلوع!!\nالمؤلف : نور عبد المجيد\nسنة النشر : 2018", "/images/products/9789777951227.webp", "9789777951227", "نساء ولكن", null, 300m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 972, "شاكر عبد الحميد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مدخل الى الدراسة النفسية للأدب\nهذا الكتاب بتناول العلاقة المتداخلة بين علم النفس والأدب ,\nتلك العلاقة التى بيرزها وجود اهتمامات عديدة بالموضوعات\nالنفسية فى مجال الأدب داخل الأعمال الأدبية, ففى بداية القرن\nالعشرين بدأ ظهور إسهامات علم النفس فى ميدان الأدب, فظهرت\nكتابات فرويد ويونج وساخس وجونز وغيرهم, وقد تباينت – كما\nيقول المؤلف – استجابات نقاد الأدب والفن وعلماء النفسإزاء ما\nقدمه علم النفس, بين المؤيد تمامًا لهذا الاتجاه, أو المعارض تمامًا له,\nوبين هؤلاء وهؤلاء وقف البعض الثالث فى مرحلة المنزلة بين\nمنزلتين ! أى بين التأييد والمعارضة!\nالمؤلف : شاكر عبد الحميد\nسنة النشر : 2018", "/images/products/9789777951272.webp", "9789777951272", "مدخل الى الدراسة النفسية للادب", null, 225m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 973, "محمد فتحى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تأتى قصص هذه المجموعة فى مفارقة غريبة لعنوانها وعلى خلاف ما يعتقد\nالقارىء.. تركز المجموعة بعمق مكثف على لقطات حياتية متنوعة .. زوج\nيبحث عن علاج لزوجته.. وأم تبحث عن راحة طفلها , لا تدرى مايخبئه لهما\nالقدر.. وطرف يقدم عرضًا رائعًا لطرف آخر , يدرك بيقين أن العرض جاء\nمتأخرًا.. وآخر يضحك حتى البكاء.. وتتضافر تلك اللقطات فى نسيج رائع\nيترسم أعماق الإنسان وآفاق الحياة المترامية , مؤكدة وجود فرصة للنجاح..\nرغم أننا حين دلفنا إلى باب لجان اختبار الزمان .. لم ينجح أحد!\nالمؤلف : محمد فتحى\nسنة النشر : 2018", "/images/products/9789777951258.webp", "9789777951258", "لم ينجح احد", null, 155m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 974, "أحمد حمدان- شريف الحجنى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "المدخل لدراسة الوساطة فى تسوية المنازعات\nإن هذا الكتاب يحمل جرثومة العدوى فاحذروه! إنه دعوة إلى منهج خاص في النظر إلى الأمور، قبل أن يكون دراسة في سبل فض المنازعات، وهو منشور تحريضي قبل أن يكون بحثا أكاديميا، وهو مدخل إلى عالم كامل من الإنسانية الرحبة، التي ترى في الطبيعة الإنسانية الخير قبل الشر، وتخاطب في البشر أسمى جوانبهم، دون أن تتركهم لنزعات العناد والصدام، واللدد والعنت، والفُجر في الخصومة، إنسانيةٍ ترى أن العلاقات بين البشر، أثرى وأعمق من أن يبترها نص قانوني جامد، أو أن يجمِّدها إجراءٌ قضائيٌّ عقيم، وترى أن العمر أقصر من أن يضيع في ردهات المحاكم، وبين ملفات الأقضية، وغرامات البنوك. إن الكتاب هذا كلُّهُ، قبل أن يكون أي شيئٍ آخر\nالمؤلف : احمد حمدان , شريف النجيحى\nسنة النشر : 2018", "/images/products/9789777951289.webp", "9789777951289", "المدخل لدراسة الوساطة فى تسوية المنازعات", null, 385m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 975, "ناصر عراق", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حين تفارق الأشياء فطريتها وطبيعتها , لاتعدو هناك قوانين حاكمة لسلوك البشر , وفق مقتضيات كونهم بشراً .. نخون أكثر من نحبهم.. ونفى بعهودنا مع أكثر من نكرههم..نضحى بأعز ما لدينا فى سبيل أحط من عرفنا .. نهجر من حلمنا بلقياهم, سعيًا وراء من كرهنا يومًا رؤياهم.. هذه رواية المتناقضات بكل عمقهاوكثافتها.. تحيا فيها الحيرة واليقين .. القرار و الاختيار .. هذه هى الرمزية الرائعة التى وضعنا فيها المؤلف حين رسم لنا البلاط , أى الحياة , مقدمًا لنا لونًا. واحدًا منها .. وتاركًا لنا المقارنة مع اللون الذى لم يذكره\nالمؤلف : ناصر عراق\n سنة النشر : 2018", "/images/products/9789777950497.webp", "9789777950497", "البلاط الاسود", null, 220m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 976, "شريف عرفة", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "علميًّا: كيف تصل لأعلى مراحل الارتقاء\nوالتطور؟ لتحقيق هذا الهدف، يأخذك الكتاب عبر الزمن\nوبين الكواكب، في رحلة بأعماق ذاتك، تخوض فيها غمار نفسك مكتشفًا أسرارها..\nبين صفحاته ستمارس تدريبات السعادة، وتعرف كيف تجني ثمار صدمات الحياة..\nكيف ينضج الحب وسط الخلافات الزوجية.. كيف تمارس السخرية الوجودية وتنمي الذكاء\nالعاطفي.. وكيف ترتقي بتجربتك الدينية ملتمسًا سبيل الحكمة.. كل هذا، طبقًا لأحدث الدراسات والأبحاث\nالعلمية! فهل أنت مستعد لخوض هذه المغامرة؟\nالمؤلف : شريف عرفة\nسنة النشر : 2018", "/images/products/9789777951302.webp", "9789777951302", "انسان بعد التحديث دليلك العلمى للارتقاء النفسى", null, 315m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 977, "محمود الوروارى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بين بلد يعيش واقعًا مُربكًا، وآخر يأتي من أعماق ماضٍ غامض. تدور أحداث هذه الرواية، من خلال أداء درامي أجاد الكاتب في طرحه، بلُغة بسيطة، وأسلوب بعيد عن المباشرة الفجَّة، مؤسِّسًا عالمًا خاصًّا به، في زمان ومكان غير مُحدَّدَين، وأحداثٍ ترتبط بطبيعة المكان وخصوصية الزمان، حيث يؤسس الشيخ النجار، ومعه آخرون، بلدًا جديدًا، ويُرسي مبادئ وقيمًا راقية، لا تنال منها ومن بلده الكبير، إلا خيانة أقرب الناس إليه!\nالمؤلف : محمود الوروارى\nسنة النشر : 2018", "/images/products/9789777951166.webp", "9789777951166", "خريف البلد الكبير", null, 210m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 978, "جابر عصفور", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "« بقيت ملاحظة ختامية عن طبيعة ما أقوم به\n في هذا الكتاب، فهو ليس تسجي للذكريات\n الشخصية فحسب، وإنما هو محاولة للجمع\n ما بين الذكرى الشخصية والذاكرة العلمية،\n في سياق لا يخلو من الإشارة السياسية. والحق\n أنني أردت أن أنقل إلى قارئ هذا الكتاب بعض\n ما تعلمته وما لاحظته على السواء، وما أسعدني\n شخصيا، وما أثراني أكاديميا.\n أعني لكل ما يجعلني أتطلع إلى زمن الذكريات\n الذاتية والعلمية بنوع من فرحة الحنين وعرفان\n المغترب بحثا عن معارف جديدة لا نهاية لتغير\n مجاليها واحتمالاتها\n المؤلف : جابر عصفور\n سنة النشر : 2018", "/images/products/9789777950947.webp", "9789777950947", "بعيداً عن مصر", null, 235m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 979, "أحمد مبارك", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“القادرون فقط هم الذين يصنعون أقدارهم، أما غير القادرين فإن أقدارهم تصنعهم”. تلك هي القيمة الرئيسية التي ينطلق منها كتابنا هذا – الذي بين يديك – مؤكدًا أن أهم ملامح هذه القدرة لمن يتمتعون بها يكمن في الثبات على المبدأ.. مهما اختلفت الأحوال وتباينت الظروف والملابسات.. ومهما تعددت التفسيرات والأيديولوجيات المتعلقة بهذا المبدأ.. في يقين تام بأن ثباتك على المبدأ ينطلق من قناعة أكيدة لديك، تعادل وجودك بأكمله؛ لإيمانك بأن أعظم القيم التي يمكن أن يحوزها أي إنسان هو أن يربح نفسه، حتى لو اضطر في سبيل ذلك إلى أن يخسر العالم بأكمله!..     يأتي د. حسام بدراوي نموذجًا مجسدًا لتلك القيمة، بشهادة مَن يخالفونه الرأي والتوجه قبل شهادة من يعاضدونه، قبل العاصفة وأثنائها وبعدها.. فكسب تقدير واحترام الجميع.. الكتاب توثيق للقيمة وجدواها في حياتنا، واحتفاء بتلك الشخصية التي عبرت عنها، ودعوة لكل الأجيال القادمة لأن تستوعب القيمة وتتمثلها في حياتها.\n\nالمؤلف : احمد مبارك\nسنة النشر : 2018", "/images/products/9789777950923.webp", "9789777950923", "رجل العاصفة", null, 100m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 980, "فتحية الدخاخنى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "دائمًا ما تسقط الأقنعة عندما يتجاوز أحد أبناء العالم النامي الحدود ويتخطى الحواجز ليترأس منظمة عالمية كبيرة كاليونسكو .. فتتكتل ضده كل القوى الكبرى لعرقلته وإفشاله وتحجيمه!.. مما يدعو للتساؤل: هل قدر أبناء هذا العالم الثالث أن يظلوا هكذا قابعين داخل بلادهم مهما كانوا نابهين ومؤهلين وقادرين؟!\nالمؤلف : فتحية الدخاخنى\nسنة النشر : 2018", "/images/products/9789777951111.webp", "9789777951111", "فاروق حسنى وأسرار معركة اليونيسكو", null, 125m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 981, "شريف شعبان", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«حاقت بمن يقترب منها أو يحاول النبش فيها.. ثبتت الفكرة المشئومة، عندما قام مدير المتحف السابق بدخول البدروم وحاول فتح الصندوق وإخراج المخطوطات لنشرها أمام العالم.. ولكنه عُثر عليه في اليوم التالي ميتًا بجواره.. مال داميان  قرب أذني مدير المتحف، يهمس له، فامتعض وجهه وانتفض من مكانه، حتى كادت تحرقه أطراف السيجارة وقال بصوت أجش: أنا لست موافقًا على هذا الأمر.. ليس عندي استعداد أن أكون مدير المتحف المقتول رقم (2)!!».\n*\nحين يغدو التاريخ بطلًا متفردًا لأحداث رواية ما.. وحين يصبح راويها الوحيد.. فارضًا سطوته على شخوصها.. وحين يجبرك التاريخ على أن يترك موقعك كقارئ يتلقى رواية، لتقاسم شخصياتها كل تلك المشاعر المتباينة في توجهاتها.. وتترواح مشاعرك مع شخوصها صعودًا وهبوطًا، تشكل هدف الإنسان في رحلته، وبين لحظات ضعف وإخفاق تعتري البشر من حين إلى آخر.. وتدرك في نهاية رحلتك مع الرواية أن الإنسان مهما بلغ تفرده وتميزه لا يستطيع الإفلات من قبضة القدر..\nـــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــــ\nد. شريف شعبان كاتب روائي وخبير في الآثار المصرية ومؤرخ فني، تخرج في كلية الآثار جامعة القاهرة، وحصل على الدكتوراه في 3102، محاضر في كلية الآثار جامعة القاهرة . له العديد من المؤلفات مثل رواية (بنت صهيون) 5102، (الأسقف ومناظرها عبر العصور) 1102، (المآدب والولائم في مصر القديمة وبلاد الإغريق وحضارة الاتروسك) 6102.\nالمؤلف : شريف شعبان\nسنة النشر : 2018", "/images/products/9789777950992.webp", "9789777950992", "ثلاث نبوءات سوداء", null, 220m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 982, "لوتس عبد الكريم", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من أجمل اللحظات في حياة أي كاتب، أن يرى أصداء عمله في عيون الآخرين، يتفاعلون مع هذا العمل، بالنقد والتحليل، أو العرض والمناقشة، وقد لقيت أعمال د. لوتس عبد الكريم، الكثير من الاحتفاء، والكثير من المناقشة، والتثمين لدورها ككاتبة ومثقفة كبيرة، لها بصمتها التي لا تنكر على الحياة الثقافية المصرية والعربية، تلك المثقفة التي اختارت طريقًا صعبًا، وثّقت من خلاله لأعلام القوة الناعمة المصرية، قابضة على مرحلة مهمة من تاريخ الوجدان والفعل المصريين، مؤرخة لمسيرة حضارية لم تنقطع في يوم من الأيام، بدءًا من كتاباتها المتصلة عن «الملكة فريدة» وإنجازها في الفن التشكيلي وحضورها الإنساني، مرورًا بيوسف وهبي، ومحمد عبد الوهاب، وإحسان عبد القدوس، وليس انتهاءً بتأسسيها مؤسسة الشموع للثقافة والفنون، كملتقى للثقافة الرفيعة. وهذا الكتاب رغم أنه حوار متصل بين عمل الكاتبة، ونخبة من ألمع العقول المصرية والعربية، فإنه في معناه الأعمق يشكل باقة ورد فوّاحة على صدر مثقفة مخلصة.\nالمؤلف : لوتس عبد الكريم\nسنة النشر : 2018", "/images/products/9789777951197.webp", "9789777951197", "لوتس فى مقام الكشف ابحاث ودراسات فى رحلة البحث عنها", null, 115m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 983, "نجيب ساويرس", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في هذا الكتاب، يضع المهندس نجيب\nساويرس، خلاصة رؤاه ومواقفه مما يجري في\nالواقع المصري والعربي، والتي نُشر أكثرها في\nبعض الصحف المصرية خلال الفترة الماضية،\nوهو برغم انشغالاته الاقتصادية الجسيمة،\nكرجل أعمال مشهور في مصر والعالم، فإنه\nلا ينسى دوره كمواطن مصري، مشارك في الحياة\nالسياسية، يمتلك الكثير من الآراء والمواقف\nالفكرية والسياسية، ويعرف قضايا ومشكلات\nواقعه، ولا يقف أمامها مكتوف اليدين، بل\nيصرّح بما يعتقد دون خوف أو مجاملة.\nالمؤلف : نجيب ساويرس\nسنة النشر : 2018\nذ", "/images/products/9789777951203.webp", "9789777951203", "مصر من غير لف ودوران", null, 220m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 984, "نبيلة السيد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لا يوجد ما يبعث السعادة ويدعو إلى القلق في نفس الوقت أكثر من استقبال مولود جديد، نعم تجربة الأمومة لأول مرة لها طعم خاص جدًّا كما أنها تحمل كل معاني الرهبة والخوف من المسؤولية، لكن هذا الإحساس بلا شك شيء يبعث على السعادة التي لا تكتمل إلَّا عندما نجد من يمد لنا يد المساعدة. في هذا الكتاب نقدم لك عزيزتي الأم في تجربتك الأولى بعض التفاصيل الخاصة باستقبال طفلك الأول والعناية به جنينًا ثم رضيعًا وحتى سن المدرسة، من خلال العناية به وتجهيز مستلزماته وغرفته، وحمايته من الأمراض المختلفة والحوادث المنزلية. كما لا يفوتنا أن نهمس في أذنك ببعض اللفتات الخاصة بالإتيكيت وتصرفات أخرى تصل بك إلى الأمومة المثالية.\nالمؤلف : نبيلة السيد\nسنة النشر : 2018", "/images/products/9789777951036.webp", "9789777951036", "انا وطفلى الاول", null, 180m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 985, "نخبة", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "المؤلف : نخبة\n سنة النشر : 2018", "/images/products/9789777951210.webp", "9789777951210", "الطريق إلى النبع", null, 140m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 986, "هالة البدرى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "نحن أمام رواية (فانتازيا) خالصة، تحلق بنا أحداثها في زمن غير معلوم ومكان لم يصل إليه واقعنا بعد.. بل إن شخصياتها نفسها جاءت مغلفة بذلك الخيال المفعم.. جاءت دلالتها الرمزية والمباشرة لتحمل صرخة احتجاج واقعية على مدى ظلم الإنسان «الفوقي» لأخيه «البدائي»، تلك الواقعية التي مكنت المؤلفة من التغلغل داخل أعماق «آدم» و«مايسة» لترسم لوحة رومانسية قادرة على تحدي قوانين “مدن السور”!\nالمؤلف : هالة البدرى\nسنة النشر : 2018", "/images/products/9789777951104.webp", "9789777951104", "مدن السور", null, 210m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 987, "صبحى موسى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في هذه الرواية تتعدد العوالم الأسطورية المليئة بالغرائبية المدهشة، حيث يحتدم الصراع بين المتصوفة والسحرة على امتلاك الحقيقة والمهدي المنتظر، وبحس ساخر يمزج المؤلف فيها بين الفنتازيا والتاريخ والأسطورة، وينسج على مهل الوقائع المؤلمة التي عاشتها قرية مجهولة على الخريطة، ليدرك الجميع في النهاية أنهم يعيشون في لغز شديد التعقيد، ولا حل للخروج منه إلا بوقفة ونقطة نظام جديدة.\nالمؤلف : صبحى موسى\nسنة النشر : 2018", "/images/products/9789777951142.webp", "9789777951142", "نقطة نظام", null, 185m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 988, "عزة بدر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“ولكن الرصاصة الطائشة العمياء، التي دوت قرب أذنه عرفت طريقها إلى الفتى، الذي ظل ممسكًا بما تبقى لديه من أعلام.. حتى هوى على الأرض.. ضمه العجوز، ولكن الفتى دفع إليه بالأعلام، احتضنها العجوز بقوة، وقد بلل وجهه الدمع.. شق طريقه رافعًا يده إلى الأعالي، وقد اشتعل غضبه: – عـَلـَمْ.. عـَلـَمْ.. عـَلـَمْ”. … يقف أبطال هذه القصص على باب الدنيا، يدقون عليه بكل ما في نفوسهم من عزائم،ورغبات، وأمنيات. … اللحظات الفريدة هي زمن هذه القصص، وأمكنتها تتشكل على هواها يوميًّا، في تلك الرحبات الواسعة. ويبدو فاتنًا أن تتأمل تلك اللحظات الفريدة، والأمكنة التي قد تعرفها، ويبدو أكثر فتنة أن تلتقي شخصيات ربما قابلتها، أو تعقد معها أواصر الصداقة، بمجرد قراءة السطور الأولى من كل قصة. … إنها رحلة التفاصيل الصغيرة والحب المُشْتَهى، والربيع القادم، وعشق الحياة!\nالمؤلف : عزة بدر\nسنة النشر : 2018", "/images/products/9789777951173.webp", "9789777951173", "على باب الدنيا", null, 155m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 989, "مصطفى نصر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا كتاب يتحدث عن الجوانب الخفية\nفي حياة العباقرة والمشاهير، تلك الخاصة\nبالزواج، ومدى تأثيره على مسيرتهم وحياتهم،\nاستعان فيه الكاتب بمخزونه الإبداعي الثري،\nوموهبته القصصية المتأججة؛ ليُقدِّم للقارئ\nمادة ثقافية مشوقة، تعرض الكثير من الأسماء\nالمعروفة، بمنظورٍ مختلفٍ، وصورةٍ قلميةٍ مغايرةٍ\nللمطروح.. ومن خلال حكايات زواج العباقرة\nوالمشاهير، أعاد الكاتب تقديم عددٍ من الأسماء\nالمعروفة عربيًّا وعالميًّا، منهم: شجر الدر، ومحمد\nعلي، وملك حفني ناصف، وفاطمة رشدي،\nوبديعة مصابني، وتولستوي، وتشايكوفسكي،\nوإبراهام لنكولن، ومصطفى كمال أتاتورك،\nوفيفيان لي، ومارلين مونرو.\nالمؤلف : مصطفى نصر\nسنة النشر : 2017", "/images/products/9789777951159.webp", "9789777951159", "حكايات زواج المشاهير والعباقرة", null, 200m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 990, "محمد محمد الحلو", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بغض النظر إن كنت مسل أو مسيحيًّا أو\nملحدًا، فإن هذا الكتاب هو أحد أهم الكتب\nالتي ستقرأها في حياتك: هل يمكن التحقق\nمن وجود خالق لهذا الكون بطريقة علمية\nلا تعتمد على توارث المعتقدات التي وجدنا\nعليها آباءنا؟!. العلم في مطلع القرن الحادي\nوالعشرين يقدم فجأة إجابة قاطعةكانت في\nالماضي مستحيلة! إنها قصة الاكتشافات العلمية\nالتي كشفت عن تفاصيل قصة الخلق من العدم\n)البج بانج(، ثم مفاجأة الاكتشافات التي\nصححت النظرية الداروينية مؤخرًا على أيدي\nالداروينيين أنفسهم، ليتخطى بذلك العلم\nمفاهيم الإلحاد العلمي الراسخ في أوروبا منذ\nقرون إلى آفاق جديدة بديعة من الروحانيات\nالعلمية.. إنها قصة الحقائق العلمية التي أثبتت مؤخرًا وجود \"مصدر\" خالق لهذا الكون بطريقة\nعلمية تتعدى المفاهيم الدارجة وتتجاوز الاختلافات بين ديانات العالم!\nالمؤلف : محمد محمد الحلو\nسنة النشر : 2017", "/images/products/9789777951128.webp", "9789777951128", "رحلة العلم من الالحاد الى الايمان", null, 160m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 991, "عمرو العادلى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدخل بك هذه الرواية إلى المنطقة التي ترى\nفيها الحلم يتماهى مع الحقيقة حتى تصبح\nالحياة سلسلة من الأوهام اللذيذة، حيث نُلبس\nالآخرين من حولنا ثيابًا من فيض خيالاتنا\nتحوِّلهم إلى كائنات ملائكية وأطياف هائمة..\nفإذا فقدت ذلك الخيط الرفيع بين الوهم\nوالحقيقة تساوى لديك ما تراه وأنت مغمض\nالعين مع ما تراه واقعًا!\nالمؤلف : عمرو العادلى\nسنة النشر : 2017", "/images/products/9789777951135.webp", "9789777951135", "اسمى فاطمة", null, 185m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 992, "يوسف عز الدين عيسى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\" الحلم نفسه الذي يتكرر، رأيت حمام السباحة ممتلئًا بالعسل بدلًا من الماء، وأنا سابحة في العسل، وماما واقفة عند حافة الحوض تقول: «كل هذا العسل من أجلك يا روحي، كلي منه واسبحي فيه، لقد أحضرته خصيصًا لك». وذقت العسل فوجدته مرًّا.. لست أدري لماذا أرى هذا الحلم مرارًا\". *                     هي رواية غير تقليدية، أحداثها متلاحقة، اعتمدت الرمزية في إيصال رسالتها .. قصر مدفون فيه الماضى و لا يراد للحاضر أن يرى النور، ترتفع أسوار حول القصر تحجب الرؤية وتزيد العزلة.. و تستمر الأحداث من خلال سياق شديد الرومانسية يجمع بين التشويق و المعنى العميق.. فهل ترمز الأسوار العالية إلى السدود و العوائق التي قد تعصف بمشاعر الإنسان؟! ــــــــــــــــــــــــــــــــــــ\nد. يوسف عز الدين عيسى، جمع بين الأدب و العلم في أعلى مستوياتهما، فهو أديب له عالمه الخاص، حصل على جائزة الدولة التقديرية في الأدب وغيرها من الأوسمة الرفيعة. تأثر أدبه بروح العصر فعبر عن الإنسان وحلل النفس البشرية بكل نوازعها وأحلامها وصراعاتها بأسلوب يتأرجح بين الحلم والواقع؛ الخيال والحقيقة.\nكسرت رواياته الحاجز التقليدي للرواية العربية فتعدى حدود الزمان و المكان، وكان من أوائل رواد الواقعية السحرية.\nالمؤلف : يوسف عز الدين عيسى\nسنة النشر : 2017", "/images/products/9789777951029.webp", "9789777951029", "العسل المر", null, 195m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 993, "جبران خليل جبران", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يحتوي هذا الكتاب على 3 قصص هي: رماد الأجيال والنار الخالدة: وهي قصة غير\n واقعية حول ابن كاهن قديم عاش في سنة 116 ق.م فقد حبيبته، إلا أن حبه لم يمت.\n مرتا البانية: يلتقي الراوي بابنها فيعلم بمرضها منه فيذهب إليها وتفتح له قلبها وتحكي له\n حكايتها مع الشاب الذي خدعها )والد الطفل( ثم تموت بعد أن تروي حكايتها كاملة.\n يوحنا المجنون: هو راعٍ في شمال لبنان، دفعه الفضول إلى قراءة \" العهد الجديد\" سرًا؛ إذ كان\n الكهنة ينهوْن بسطاء الناس عن قراءته.\nالمؤلف : جبران خليل جبران\n سنة النشر : 2017", "/images/products/9789777951043.webp", "9789777951043", "عرائس المروج", null, 95m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 994, "رشا سمير", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذه الرواية هي قصة حُب لم يألفها البشر..\n عشق له مذاق خاص. لم تكتبه الماديات ولم\n تصنعه الثوابت.. بل صنعته الأقدار.. إنهما\n روحان تعانقا لينسجا مجموعة من المشاعر\n الإنسانية التي رسمت لهما طريقين مختلفين،\n يتقاطعان في تلك القلعة البعيدة.. جمعتهما يد\n القدر ليرويا قصتهما .. لا يفصلهما عام بل\n تفصلهما أعوام..\n إنها رواية تجمع فيها الكاتبة بحرفية بين الواقع\n المُربك الحزين، والخيال الغامض الأثير..\nالمؤلف : رشا سمير\n سنة النشر : 2017", "/images/products/9789777951067.webp", "9789777951067", "سألقاك هناك", null, 300m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 995, "عائشة البصري", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذه مجموعة قصصية متباينة أبدعتها المؤلفة، وهي تقاوم مشاعر حزن دفينة حاولت أن تدفعها بسطور أكثر إشراقًا، فجاءت هذه التنويعة الثرية الجميلة وهي معبأة بمشاعر مختلطة من الشجن والتفاؤل!\nالمؤلف : عائشة البصرى\nسنة النشر : 2017", "/images/products/9789777951074.webp", "9789777951074", "بنات الكرز", null, 140m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 996, "زينب عفيفي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عندما تصطدم أذناك وتقرأ عيناك عنوان روايتنا\nتلك، فمن المؤكد أنك ستتساءل «ثم ماذا » ولك\nالحق كل الحق في ذلك.. ولكنني نيابة عن البطلة\nأجيب لك عن سؤالك هذا بقولي: «... فأهديته\nخطابًا ».. هذه الرواية جاءت في نسق رائع،\nرسالة، أوردت فيها البطلة كل مشاعرها الحالمة\nوالسعيدة والمنكسرة ورسمت لنا بانوراما محبوكة\nالنسج، جعلتنا نقتحم سطور الرسالة، ونشارك\nأبطالها أحمد وليلى وعمر ونادين.. وغيرهم تلك\nالرحلة، بكل زخمها ولقطاتها المضيئة والباهتة،\nثم الحياة بكل مسئولياتها وأفراحها وأتراحها،\nالتي تباعد بيننا، كلٌّ في طريق.. حتى إذا واتتنا\nالفرصة لأن نستعيد ما سلبه الزمن منا، نكتشف\nأن القطار وصل إلى محطته متأخرًا!\nالمؤلف : زينب عفيفى\nسنة النشر : 2017", "/images/products/9789777951005.webp", "9789777951005", "اهدانى حبا", null, 150m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 997, "وسيم السيسي", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قبل أن تُدرك الدنيا حقيقة وجودها، وقبل أن\n ينتبه التاريخ من غفوته الاستثنائية، كانت مصر\n حديقة غنَّاء، تحوي زهور الحضارة والرُّقي\n الإنساني، التي زرعها أبناؤها بعبقرية ما زالت\n تُدهش البشرية، وستظل. إنها حديقة مبهرة،\n زهورها: العدالة، والدين، والطب، والهندسة،\n والعمران، والنقاء الكامن في زهرة اللوتس\n المقدسة.. وما زالت ثمار هذه الحديقة يانعة،\n رغم مرور آلاف السنين.\n إلى هذه الحديقة الغنَّاء، يأخذنا د. وسيم\n السيسي في رحلة شيقة عَ هذا الكتاب؛\n لنستنشق بديع أزهارها، ونتعرف إلى رموزها\n وعباقرتها؛ وقبل أن نعود معه من هذه الرحلة\n المدهشة، نُدرك أن مصر التي بدأت الحضارة منذ الأزل، ستبقى بأسرارها العبقرية إلى الأبد!\n المؤلف : وسيم السيسى\n سنة النشر : 2017", "/images/products/9789777951050.webp", "9789777951050", "فى البدء كانت مصر", null, 185m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 998, "عزت القمحاوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذه الرواية تجمع باحترافيَّةٍ بين قلبين تفصل بينهما سنواتٌ من الشجن والتجلي، عَبْرَ لُغةٍ رصينةٍ، ونسيجٍ سردي متين، وإحساسٍ رشيقٍ، يكاد يلمس تخوم الروح، يُحلِّق في فضاء تلك العلاقة الاستثنائية، بين محامٍ مخضرمٍ، سرقته دوامات الحياة، فلم يخرج منها إلا بصروحٍ أقرب إلى الأوهام، وفتاة محاطة بإحباطات الفقد، مندفعة بلهفة الفضول إلى علاقة تبدو لمَن يراها من الخارج غير منطقية، تاركة للواقع فرصة أن يقول كلمته الأخيرة!\nالمؤلف : عزت القمحاوى\nسنة النشر : 2017", "/images/products/9789777951012.webp", "9789777951012", "يكفى اننا معا", null, 185m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 999, "مصطفى الفقي", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تلك الرحلة التي تنوعت مجالاتها وشخصياتها\n في شتى المحافل الدبلوماسية والسياسية\n والاجتماعية والثقافية والعلمية.. يقدم كل\n ذلك كحق واجب للأجيال الحاضرة والقادمة\n في المعرفة والتقييم والاستفادة.. ونظرًا للتنوع\n الثري للغاية لدى مؤلفنا فيمن قابلهم أو قرأ\n لهم أو سمع عنهم، قام المؤلف بتقسيم رحلته\n إلى أربع محطات رئيسة، تبدأ أولاها بالمرأة، في\n إشارة واضحة إلى قدرها، فتأتي المحطة الأولى\n «نساء شهيرات » مثل: إنديرا غاندي وتحية\n عبد الناصر ود. عائشة راتب والأميرة ديانا..\n وكثيرات غيرهن.. ثم تأتي محطته الثانية -\n احتفاءً بالعلم - في محراب الجامعة، فتقرأ عن د.\n إبراهيم بدران، ود. أحمد شوقي العقباوي، ود.\n أحمد مستجير، ود. سليمان حزين وغيرهم..\n المؤلف : مصطفى الفقى\n سنة النشر : 2017", "/images/products/9789777950886.webp", "9789777950886", "شخصيات على الطريق", null, 300m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 1000, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إنها تتعذب، ولا تدري سر عذابها.. كل\n منهما لا يدري.. لأن أحدا منهما لم يستطع أن\n يرى الخيط الرفيع.. الرفيع جدا.. الذي يفصل\n بين الحب وغريزة التملك..\n عاطفة الحب التي تسمو بك إلى مرتبة\n الملائكة..\n وغريزة التملك التي تنحط بك إلى مرتبة\n الحيوان..\n الحب الذي يدفعك إلى أن تضحي بنفسك في\n سبيل من تحب، وغريزة التملك التي تدفعك\n إلى أن تضحي بمن تحب في سبيل نفسك..\n المؤلف : احسان عبد القدوس\n سنة النشر : 2017", "/images/products/9789777950978.webp", "9789777950978", "الخيط الرفيع", null, 170m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 1001, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "والواقع أني كنت أبحث عنك إلى أن وجدتك\n لأني في حاجة إلى أن أعيش فكرك الذي تعودت\n عليه ليصور لي المستقبل.. فأنا حائر إلى أقصى\n حدود الحيرة.. لم أعد أستطيع أن أرى صورة\n للمستقبل.. وقال منير في هدوء: - أي مستقبل؟\n وقال عباس في عنف:\n - مستقبل بلدنا.. مستقبل الحالة التي\n نعيشها..\n المؤلف : احسان عبد القدوس\n سنة النشر : 2017", "/images/products/9789777950985.webp", "9789777950985", "الحياة فوق الضباب", null, 185m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 1002, "علي عطا", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هل يمكن يا ألله، أن يصبح الكوثرُ وطنًا بديلًا لناسِه الوافدين إليه رغمًا عنهم من كل صوبٍ وحدب؟ هو بات كذلك بالفعل، ولا بديل له إلا شوارعُ لا ترحم ساكنيها. الكوثرُ، تصلُ إليه نسماتُ النيل، يا طاهر، وتؤنسُ أهلَه عصافيرُ تسكنُ فوق شجرة توتٍ، وقِططٌ تتوالد في الفناء الضيق، ولا يمكن أن ترى أيًّا منها في محيط غرف أهل المكان من البشر الذين ينامون في أول الليل أمام شاشة التلفزيون، بتأثيرِ عقاقير، مختلفة الألوان والأحجام، ويستيقظون منهكين، مع أول ضوء، ليتناولوا شايًا بحليبٍ مع سجائر متتالية، قبل الإفطار المقترن بحصة جديدة من العقاقير\nالمؤلف : على عطا\nسنة النشر : 2017", "/images/products/9789777950930.webp", "9789777950930", "حافة الكوثر", null, 150m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 1003, "سعيد توفيق", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الصورة الذهنية الشائعة لدى الكثيرين من المسلمين هي أن الفن لا صلة له بالدين، فهما موضوعان مختلفان. غير أن هذا التصور يعبر عن فهم ضحل أو مغلوط لا يفطن إلى ما هنالك من صلة حميمة بين الفن والدين. فالفن والدين في الأصل مرتبطان ارتباطًا وثيقًا، فهما موضوعان ملتحمان في الوعي الإنساني منذ أن حاول الإنسان عبر التاريخ التعبير عن نفسه من خلال أنشطة قصدية لا تتوجه بفعل الغريزة فحسب: فالإنسان البدائي قد وعى المقدس باعتباره قوة هائلة غامضة تتحكم في حياته ومصيره، ولذلك يشعر إزاءها بمشاعر متباينة ومتداخلة من الرهبة والروعة والإجلال. كما أننا نشهد ذلك في فن المعمار عند القدماء وفي العصر الوسيط المسيحي والإسلامي. كما أن المساجد قد عبرت بأشكال مختلفة عن وعي المسلمين بوحدانية الإله التي تتجسد في المئذنة التي تشبه الواحد كعدد وهيئة، والتي تتجسد أيضًا في الإحساس باللانهائية الذي يتجلى في المنمنمات والأشكال الهندسية التي تتكرر إلى مالا نهاية. وهذا ما تشهد به أيضًا لوحات التصوير المسيحي في العصر الوسيط، التي تصور غالبًا الروح المسيحية التي تعبر عن نفسها في حالة من السكينة والطمأنينة، كما تتجلى في وجوه وإيماءات العائلة المقدسة والقديسين. فما الذي حدث ليفصم عُرى الصلة الحميمة بين الفن والدين، ويسـيء إلى الفن والدين معًا في واقعنا الثقافي؟ الواقع أن هذا الانفصام نشأ على مراحل، واتخذ أساليب متنوعة ومتباينة.. وذلك ما سيتبينه القارئ من خلال سطور هذا الكتاب المتميز.\nالمؤلف : سعيد توفيق\nسنة النشر : 2017", "/images/products/9789777950954.webp", "9789777950954", "تأويل الفن والدين", null, 185m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 1004, "شريف صالح", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“انتشر “هاشتاج زوكربرج فضحنا”، وسرعان ما امتلأ بالنكات والشتائم ضد مارك زوكربرج الذي سرق بوستات ملايين الناس وأسرارهم وأعمارهم ثم تخلى عن الموقع وتركه ينهار هكذا. ابن العاهرة! لماذا أخذنا على غفلة ولم يخبرنا بموعد الانهيار؟ ولم يكن علي نجيب ليفوّت فرصة المشاركة في “الهاشتاج”: “اسمحوا لي بسؤال يا أصدقائي: لماذا يستثار فضولنا لدخول الموقع كل لحظة وكتابة كل ما يدور في وعينا؟! أليس ما نمارسه أشبه بعرض “إستربتيز”؟! كل منا يمارس رقصته المفضلة. ساعتها نكتشف أننا لا نتصفح “الفيسبوك” بل “الفيسبوك” هو الذي كان يتصفحنا”!\nالمؤلف : شريف صالح\nسنة النشر : 2017", "/images/products/9789777950893.webp", "9789777950893", "حارس الفيسبوك", null, 150m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 1005, "فاروق شوشة", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "نخلة الماء – الديوان الأخير\nلا طعم موتٍ، مشبهٌ موْتًا سواهُ فكلُّ فقدٍ لوعةٌ لها مذاقُها الجديد وساعةُ الرحيل مُرّةً لكنها تلازمُ الحياة وطعمها مختلفٌ، لأنها مقرونةٌ بِهوْلة الفقيد وهكذا نظلُّ دومًا في مدارج الحياة قلوبنا منذورةٌ لراحلٍ جديد\nالمؤلف : فاروق شوشة\nسنة النشر : 2017", "/images/products/9789777950909.webp", "9789777950909", "نخلة الماء", null, 140m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 1006, "مي التلمساني", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حديث إلى النفس الحالمة يلمس شغاف القلوب لمسًا رقيقًا ويعزف على أوتارها لحن الرجوع.. هو حديث يرتد بك إلى الماضي ويردك إلى الحاضر في لحظة فارقة، حين يمتزج الحلم بالواقع والخيال بالمعقول في حوار رائق طرفاه الممكن واللا ممكن!\nالمؤلف : مى التلمسانى\nسنة النشر : 2017", "/images/products/9789777950916.webp", "9789777950916", "عين سحرية", null, 150m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 1007, "للجاحظ", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لا ترجع أهمية كتاب \"البخلاء\" للجاحظ إلى كونه واحدًا من عيون التراث الأدبي العربي فحسب، ولكن تكمن تلك الأهمية في معنى الفرادة، تلك التي يتميّز بها أسلوب الجاحظ، وفي جوهر فكرة الحداثة - التي إن تحققت في عمل أدبي لحقت به في كل العصور - ثم في الجِدّة والإحاطة، وهما صفتان وسمتا مؤلفاته، وجعلتاها منبعًا صافيًا للمتعة وتجدُّد القيمة.\n   هنا، نطالع صورةً بانورامية للمجتمع الذي عاش فيه المؤلف بجميع طبقاته وأفراده. نتحسّسُ تفاصيلَ ملامحهم وخصائصَهم النفسية من غير تصنُّعٍ ولا مداراة. وعبر حكاياتِ الكتاب تنتقلُ النبرةُ من لسانٍ إلى لسان، حيث ينطقُ العامةُ والنَّوْكى والحمقى والصعاليكُ والزُّطُّ واللصوص، وينطق الخلفاءُ والأمراءُ والوزراءُ وقُوّادُ الدولة وكبارُ كُتابها.\n   وإذا نطقَ كلُّ هؤلاء، فلا غَرْوَ أن تنبحَ كلابُهم، وتعويَ ذئابُهم، وتصيحَ ديوكُهم البخيلة وهي تعدو، كي تسلبَ الحَبَّ من مناقير الدجاج.\n   يتخفى الجدُّ في ثوب الهزل، وينقلب الهزلُ جدًّا، وتتحركُ مفرداتُ اللغة عفيةً حرةً عبر القرون، حتى تتراقصَ حروفُها حيةً نابضةً أمام عيوننا.\n المؤلف : الجاحظ\n سنة النشر : 2017\n\nتقديم صلاح فضل", "/images/products/9789777950350.webp", "9789777950350", "البخلاء", null, 400m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 1008, "نور عبد المجيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أنت لا تعرف ماذا تريد منك الحياة!! أنت\nلا تعلم أي الطرق إلى النجاة يقودك!! أنت في\nكل الأحوال تغمض عينيك وتتبع قلبك.. قد\nترى عيناك الدروب المرسومة..\nلكن وحده قلبك الذي بين الحنايا يرى\nنهاياتها!!\nكل ما عليك أن تُنقي قلبك.. أن تُطهره..\nوحين تضعك الحياة على مفترق الدروب\nالسوداء.. أغمض عينيك واتبع قائدك.. اتبع\nقلبك!! ثقتك ليست في الاختيار أبدًا.. رجاؤك\nكله في طهر القائد ونقائه!!\nالمؤلف : نور عبد المجيد\nسنة النشر : 2017", "/images/products/9789777950794.webp", "9789777950794", "ذكريات محرمة", null, 360m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 1009, "خالد عزب", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يرجع علماء الاثار أن اول ظهور للانسان على الارض منذ حوالى 200.000 سنة مضت على أقل تقدير, مرت منها 140.000 سنة دون تحول كبير فى نمط حياة هذا الانسان أو ظهور بوادر لخطوات تنبىء عن تقدم ما فى حياته, فماذا حدث وأدى الى تحول فى قدرة الانسان على التفكير والابتكار, كابتكار الادوات الحجرية والرسم على جدران الكهوف؟!\nان قدرة الانسان على التفكير تجعله مختلفا عن سائر الكائنات, حيث تقع هذه الأجزاء المسئولة عن التفكير فى القشرة الخارجية للمخ, وهى مع مراكز الذاكرة فى المخ تساعدنا على الربط بين الماضى والحاضر وتصور المستقبلوالسؤال الملح الآن هو : لماذا لم يقم الفرد بتنمية ذاكرته بيولوجيا على غرار الانسان البدائى أو انسان الغابة الذى يرى بعض العلماء أن الذاكرة نمت لديه بيولوجيا, أم خلق الانسان والذاكرة جزء أساسى منه؟!\nالمؤلف : خالد عزب\nسنة النشر : 2016", "/images/products/9789777950862.webp", "9789777950862", "الاثار شفرة الماضى اللغز والحل", null, 185m, new DateTime(2014, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 1010, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«وقال عبد الرحمن وهو في منتهى الاشمئزاز:\n - لقد قلت إن الموسيقى الحلال هي التي تحقق\n إمتاع الروح من خلال استماع الأذنين.. فإن أدت\n إلى تحريك الجسد فهي موسيقى حرام.. وهذه\n الموسيقى الأجنبية تحرض على تحريك الجسد..\n كأن كل جسد يقوم بدعوة إلى الحرام!\n المؤلف : احسان عبد القدوس\n سنة النشر : 2016", "/images/products/9789777950855.webp", "9789777950855", "فوق الحلال والحرام", null, 225m, new DateTime(2016, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false }
                });
